### Description
This PR adds `VehicleEvents` to the DIMO object in the SDK.

- Adding Vehicle Events API to the SDK
- Adding `/api` path to jest.config to use /api path imports.
- Formatting code with Prettier

### Checklist

- [x] I fully tested it as developer

### How to test it?

- Create a simple python backend to pass webhook verifications from the API. 
<details><summary>Python Code</summary>

```python
from http.server import BaseHTTPRequestHandler, HTTPServer

class SimpleHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        post_data = self.rfile.read(content_length)
        print("Received POST data:", post_data.decode('utf-8'))

        self.send_response(200)
        self.send_header("Content-Type", "text/plain")
        self.end_headers()
        self.wfile.write('token'.encode()) # sending "token" as the verification token

    def log_message(self, format, *args):
        return

if __name__ == "__main__":
    server_address = ('', 8080)
    httpd = HTTPServer(server_address, SimpleHandler)
    print("HTTP server started on port 8080...")
    httpd.serve_forever()

```

</details>

- Run your Python API.
- Use Ngrok to make your Python API accessable from the internet.
- Create a `test.ts` file in `api/resources/VehicleEvents`

<details>
<summary>Test file</summary>

```typescript
/** @format */

import { getDeveloperJwt } from "api/functions";
import { DIMO } from "../../../dimo";
import { WebhookDefinitionParams, WebhookUpdateParams } from ".";

const testTokenId = 178893;
const cbUrl = "https://constantly-sweet-cardinal.ngrok-free.app";

describe("VehicleEvents Resource", () => {
	let dimo: DIMO;
	let developerJwt: string;
	let createdWebhookId: string | undefined;
	let allVehiclesWebhookId: string | undefined;

	beforeAll(async () => {
		dimo = new DIMO("Production");

		const submit = await getDeveloperJwt(
			{
				client_id: "client_id",
				domain: cbUrl,
				private_key: "private_key",
				address: "client_id",
			},
			"Production",
		);
		developerJwt = submit.headers.Authorization;
	});

	it("should list all webhooks", async () => {
		const webhooks = await dimo.vehicleEvents.listWebhooks(developerJwt);
		expect(Array.isArray(webhooks)).toBe(true);
	});

	it("should get available signal names", async () => {
		const signalNames = await dimo.vehicleEvents.getWebhookSignalNames(
			developerJwt,
		);
		expect(Array.isArray(signalNames)).toBe(true);
	});

	it("should create a new webhook", async () => {
		const params = {
			service: "Telemetry",
			data: "powertrainTransmissionTravelledDistance",
			trigger: "valueNumber > 1000",
			setup: "Realtime",
			description: "Trigger when travelled distance exceeds 1000",
			target_uri: cbUrl,
			status: "Active",
			verification_token: "token",
		} as WebhookDefinitionParams;
		const created = await dimo.vehicleEvents.createWebhook(
			developerJwt,
			params,
		);
		expect(created).toHaveProperty("id");
		createdWebhookId = created.id;
	});

	it("should subscribe a vehicle to the webhook", async () => {
		if (!createdWebhookId) return;
		await dimo.vehicleEvents.subscribeVehicle(
			developerJwt,
			createdWebhookId,
			testTokenId,
		);
	});

	it("should list subscribed vehicles", async () => {
		if (!createdWebhookId) return;
		const subscribedVehicles = await dimo.vehicleEvents.listSubscribedVehicles(
			developerJwt,
			createdWebhookId,
		);
		expect(Array.isArray(subscribedVehicles)).toBe(true);
	});

	it("should list vehicle subscriptions", async () => {
		const vehicleSubscriptions =
			await dimo.vehicleEvents.listVehicleSubscriptions(
				developerJwt,
				testTokenId,
			);
		expect(Array.isArray(vehicleSubscriptions)).toBe(true);
	});

	it("should update webhook configuration", async () => {
		if (!createdWebhookId) return;
		const params = {
			webhookId: createdWebhookId,
			service: "Telemetry",
			data: "powertrainTransmissionTravelledDistance",
			trigger: "valueNumber > 10000",
			setup: "Realtime",
			description: "Trigger when travelled distance exceeds 10000",
			target_uri: cbUrl,
			status: "Active",
			verification_token: "token",
		} as WebhookUpdateParams;
		const updated = await dimo.vehicleEvents.updateWebhook(
			developerJwt,
			createdWebhookId,
			params,
		);
		expect(updated).toHaveProperty("id", createdWebhookId);
	});

	it("should unsubscribe vehicle", async () => {
		if (!createdWebhookId) return;
		await dimo.vehicleEvents.unsubscribeVehicle(
			developerJwt,
			createdWebhookId,
			testTokenId,
		);
	});

	it("should delete webhook", async () => {
		if (!createdWebhookId) return;
		await dimo.vehicleEvents.deleteWebhook(developerJwt, createdWebhookId);
		createdWebhookId = undefined;
	});

	it("should create a webhook for all vehicles", async () => {
		const params = {
			service: "Telemetry",
			data: "powertrainTransmissionTravelledDistance",
			trigger: "valueNumber > 1000",
			setup: "Realtime",
			description: "All vehicles test",
			target_uri: cbUrl,
			status: "Active",
			verification_token: "token",
		} as WebhookDefinitionParams;
		const created = await dimo.vehicleEvents.createWebhook(
			developerJwt,
			params,
		);
		expect(created).toHaveProperty("id");
		allVehiclesWebhookId = created.id;
	});

